local function IsInstanceOf(obj, typeName)
	local current = obj

	while current do
		if not current._type_name then
			return false
		end

		if current._type_name == typeName then
			return true
		end

		if not current.__base_type then
			return false
		end

		current = current.__base_type
	end

	return false
end

